properties.entry:
		
        select * from (
                select row_number() over (partition by req_date::date,a.req_id order by b.guest_id),b.guest_id,
                a.req_id,b.name,b.gender,a.from_date,a.to_date,a.req_date
                 FROM gad_request a JOIN guest_details b ON a.req_id = b.req_id
                where a.status='REQ'and (a.mode_of_req='GAD' or a.mode_of_req='PUB') and  a.req_id NOT IN (select req_id from mod_req_room) and a.from_date > current_date - 5 ORDER BY req_date DESC
               ) f1 where f1.row_number = 1;
